@@ -434,9 +434,15 @@ public class TestFunctionQuery extends SolrTestCaseJ4 {

   @Test
   public void testSortByFunc() throws Exception {
-    assertU(adoc("id", "1", "const_s", "xx", "x_i", "100", "1_s", "a"));
